public boolean hasPair(int[] values, int target) {
    Set<Integer> seen = new HashSet<>();
    for (int v : values) seen.add(v);
    for (int v : values) if (seen.contains(target - v)) return true;
    return false;
}

items.solution:
public boolean hasPair(int[] values, int target) {
    Set<Integer> seen = new HashSet<>();
    for (int v : values) {
        if (seen.contains(target - v)) return true;
        seen.add(v);
    }
    return false;
}
